  /** [block, count] most common first. */
  census() {
    const m = new Map();
    for (const c of this.solids()) m.set(c.block, (m.get(c.block) || 0) + 1);
    return [...m.entries()].sort((a, b) => b[1] - a[1]);
  }

  toTag() {
    const palette = [], index = new Map(), blocks = [];
    for (const c0 of this.cells.values()) {
      const c = withDefaults(c0);
      const pk = c.block + JSON.stringify(c.state ? Object.entries(c.state).sort() : []);
      if (!index.has(pk)) {
        index.set(pk, palette.length);
        const e = { Name: t.string(c.block) };
        if (c.state) e.Properties = t.compound(Object.fromEntries(Object.entries(c.state).map(([k, v]) => [k, t.string(v)])));
        palette.push(e);
      }
      const b = { pos: t.list("int", c.pos), state: t.int(index.get(pk)) };
      if (c.nbt) b.nbt = c.nbt;
      else { const be = blockEntityOf(c.block); if (be) b.nbt = t.compound({ id: t.string(be) }); }   // loaders that don't make one render the block broken
      blocks.push(b);
    }
    return t.compound({
      DataVersion: t.int(this.dataVersion),
      size: t.list("int", this.size),
      palette: t.list("compound", palette),
      blocks: t.list("compound", blocks),
      entities: this.entities ?? t.list("compound", []),
    });
  }

  /** Write a gzipped structure .nbt, or a Litematica schematic when the path ends in .litematic. */
  save(path) {
    if (/\.litematic$/i.test(path)) return saveLitematic(this, path);
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, write(this.toTag()));
    return path;
  }
}

/** Read a structure .nbt (first palette if the file has several) or a .litematic (every region) into a Grid. */
export function load(path) {
  const { tag } = parse(readFileSync(path));
  if (isLitematic(tag)) return fromLitematic(tag);
  const v = tag.value;
  if (!v.size || !(v.palette || v.palettes) || !v.blocks) throw new Error(`${path}: not a structure .nbt`);
  const palette = simplify(v.palette ?? { type: "list", value: v.palettes.value.value[0] ? { type: "compound", value: v.palettes.value.value[0].value } : { type: "compound", value: [] } });
  const g = new Grid(simplify(v.size), { dataVersion: v.DataVersion ? v.DataVersion.value : DATA_VERSIONS["1.21.4"], entities: v.entities ?? null });
  for (const b of v.blocks.value.value) {
    const pos = simplify(b.pos ? { type: "list", value: b.pos.value } : b.pos);
    const p = palette[b.state.value];
    g.set(pos[0], pos[1], pos[2], p.Name, p.Properties, b.nbt);
  }
  return g;
}
